INSERT INTO `actualite` (`id`, `titre`, `contenu`, `image`, `categorie`, `date_evenement`, `lieu`, `a_la_une`, `published_at`) VALUES
(2, '2e Grand Salon des arts de la F.F.A.P.', 'La Federation Francaise des Arts Plastiques (FFAP) a le plaisir d\'annoncer la tenue du 2e Grand Salon des Arts, un rendez-vous incontournable dedie a la creation sous toutes ses formes.\r\n\r\nDu 4 au 7 mars 2027, le Forum du Casino de Hyeres deviendra un veritable laboratoire artistique ou se rencontreront talents confirmes, jeunes createurs, collectifs et passionnes d\'art contemporain. Apres le succes de sa premiere edition, le Salon revient avec une ambition renouvelee et une programmation enrichie.\r\n\r\nLes nouveautes de cette edition\r\n\r\nPour cette deuxieme edition, la FFAP innove et enrichit l\'experience des visiteurs avec plusieurs nouveautes marquantes :\r\n\r\n- Des stands habilles de tissus, proposes en deux harmonies de couleurs (tons chauds et tons froids), offrant une esthetique plus immersive et elegante, pensee pour sublimer chaque univers artistique.\r\n- Des demonstrations de Live Painting, permettant au public d\'assister en direct a la naissance d\'une oeuvre, dans une ambiance vibrante et participative.\r\n- Un espace Street Art, ou les artistes urbains realiseront des fresques et performances en temps reel.\r\n- La peinture sur vetement, nouvelle discipline mise a l\'honneur, fusionnant art visuel et expression textile.\r\n- Un defile exceptionnel, presentant les creations realisees pendant le salon : pieces uniques, vetements peints, silhouettes inspirees de l\'univers graphique de l\'affiche officielle, entre couleurs eclatantes, formes polygonales et energie contemporaine.\r\n\r\nUn large eventail de disciplines\r\n\r\nAu-dela de ces nouveautes, le Salon continuera d\'accueillir un large eventail de disciplines : peinture, sculpture, dessin, photographie, arts numeriques, installations, street art, ainsi que des espaces dedies aux associations et createurs independants.\r\n\r\nAvec cette edition renouvelee, la FFAP affirme sa volonte de celebrer l\'art sans limites, de favoriser les rencontres, et d\'offrir au public une experience artistique riche, vivante et audacieuse.\r\n\r\nInformations pratiques\r\n\r\nLe Salon est ouvert au public du 4 au 7 mars 2027, au Forum du Casino de Hyeres. Horaires, tarifs et modalites d\'inscription pour les exposants seront precises prochainement sur le site de la FFAP.', '/uploads/1787236807707.png', 'evenement', '2027-03-03', 'Forum du Casino de Hyeres', 0, '2026-08-20 14:40:07'),
(3, 'Sortie Avignon — Le palais des Papes', 'La Federation Francaise des Arts Plastiques a egalement organise une sortie culturelle a Avignon visiter le Palais des Papes, reunissant un groupe d\'adherents autour d\'une journee de decouverte artistique et patrimoniale. Entre patrimoine historique, lieux emblematiques et espaces d\'exposition, cette escapade a permis d\'explorer la richesse culturelle de la ville.\r\n\r\nDans une atmosphere conviviale, les participants ont pu echanger autour des oeuvres, des lieux visites et de leurs propres pratiques artistiques. Cette sortie a ete l\'occasion de nourrir la curiosite, de partager des impressions et de renforcer les liens au sein de la Federation.\r\n\r\nEn proposant ce type de rendez-vous, la Federation Francaise des Arts Plastiques poursuit son engagement en faveur de la rencontre entre les artistes, les amateurs et les lieux de culture. D\'autres sorties et evenements seront programmes afin de continuer a offrir des moments de decouverte, de dialogue et de plaisir partage autour de l\'art.', '/uploads/1787241074846.png', 'sorties', '2026-01-17', 'Avignon', 0, '2026-08-20 15:45:22'),
(4, 'Sortie au Chateau La Coste', 'Le 25 octobre 2025, la Federation Francaise des Arts Plastiques a organise une journee de decouverte au Chateau La Coste, reunissant un groupe de cinquante participants. Dans un cadre melant art, architecture et nature, cette sortie a ete l\'occasion de partager un moment convivial autour de la creation contemporaine.\r\n\r\nLa meteo particulierement agreable a permis de profiter pleinement du site, des promenades en exterieur et des oeuvres disseminees dans le paysage. Entre sculptures monumentales, installations et expositions, les participants ont pu faire de belles decouvertes artistiques tout au long du parcours.\r\n\r\nCette journee a egalement favorise les echanges entre artistes et amateurs d\'art, dans un esprit de rencontre et de partage. Chacun est reparti enrichi de nouvelles inspirations, de points de vue croises et du souvenir d\'un moment chaleureux passe ensemble.\r\n\r\nEn proposant ce type de sortie culturelle, la Federation Francaise des Arts Plastiques poursuit sa mission de valorisation de la creation artistique et de mise en lien des publics avec des lieux d\'art majeurs.', '/uploads/1787388818304.jpeg', 'sorties', '2025-10-25', 'Chateau La Coste', 0, '2026-08-22 08:53:38'),
(5, 'Salon des Arts Contemporains — Hyeres', 'Du 30 avril au 3 mai 2026 — Forum du Casino a Hyeres\r\n\r\nLa Federation Francaise des Arts Plastiques organise son Salon des Arts Contemporains au Forum du Casino a Hyeres, avenue Ambroise Thomas, du 30 avril au 3 mai 2026. Cet evenement rassemblera peintres, sculpteurs, dessinateurs, aquarellistes, photographes et artisans d\'art venus de toute la France pour quatre jours de creation et de rencontres avec le public.\r\n\r\nLes invitees d\'honneur de cette edition seront les Bombaspheres, un collectif d\'artistes parisiennes specialise dans le street art. Chaque jour, un show unique sera propose, avec des performances en direct et la realisation d\'oeuvres sur place, offrant aux visiteurs l\'occasion d\'assister au travail des artistes en temps reel.\r\n\r\nLe salon sera ouvert de 10h a 19h, avec une entree gratuite, afin de permettre au plus grand nombre de decouvrir la diversite des pratiques artistiques contemporaines. Une restauration sur place sera egalement proposee pour profiter pleinement de la journee.', '/uploads/1787390669373.jpg', 'evenement', '2026-04-30', 'Forum du Casino, avenue Ambroise Thomas, Hyeres', 0, '2026-08-22 09:24:29');
