INSERT INTO `artiste` (`id`, `nom`, `discipline`, `bio`, `photo`, `created_at`) VALUES
(1, 'Martine de Santis', 'Peinture, Sculpture', 'Depuis sa retraite en 2015, Martine de Santis consacre une grande partie de son temps a ses passions artistiques : la peinture et la sculpture. Ces deux pratiques, qu\'elle mene en parallele, lui permettent d\'exprimer sa creativite tout en continuant, a chaque oeuvre, a explorer de nouvelles techniques et de nouvelles sensibilites.\r\n\r\nPour Martine, creer est avant tout une source de plaisir, d\'evasion et de rencontres. Chaque toile ou sculpture est une nouvelle aventure, l\'occasion de traduire une emotion, une intuition ou un regard singulier sur le monde qui l\'entoure.\r\n\r\nPresidente des Artistes Gardeens\r\n\r\nMartine de Santis preside l\'association Les Artistes Gardeens, basee a La Garde, dans le Var. L\'association a pour vocation de promouvoir l\'art sous toutes ses formes — peinture, aquarelle, huiles, modelage, dessin, vitraux — a travers des cours, des ateliers libres et des expositions organisees tout au long de l\'annee, notamment lors du Salon de Printemps et des expositions a la salle Gerard Philipe.\r\n\r\nA la tete de cette structure, elle coordonne l\'organisation des activites, des expositions et des projets de l\'association, tout en favorisant les echanges entre les membres et les clubs partenaires. Cet engagement associatif lui permet de partager sa passion de l\'art avec un large public et de contribuer activement a la vie culturelle de sa commune.\r\n\r\nPresider une association d\'artistes est pour elle une experience aussi enrichissante que sa pratique personnelle : elle y trouve un sens supplementaire a son engagement, entre transmission, organisation et vie collective autour de la creation.', '/uploads/1787145689750.jpg', '2026-08-18 12:34:20'),
(2, 'Christian Disty', 'Peinture', 'Christian Disty est ne a Bruxelles, en Belgique, le 18 janvier 1950. Installe en France depuis 2012, il vit a Bormes-les-Mimosas, ou il poursuit son parcours artistique.\r\n\r\nArtiste depuis plus de cinquante ans, il a mene l\'essentiel de sa carriere dans l\'univers de la magie, presentant ses spectacles a travers le monde aux cotes de son epouse, egalement son assistante de scene.\r\n\r\nDe la magie a la peinture\r\n\r\nA la retraite, il realise un reve de longue date en se consacrant a la peinture. Cette nouvelle passion l\'amene a rapprocher ses deux univers artistiques : la magie et les arts plastiques. De cette rencontre naissent les Tableaux Magiques, des oeuvres concues pour la scene, permettant aux magiciens de faire apparaitre ou disparaitre des objets ou des animaux directement depuis le tableau.\r\n\r\nAu-dela de ce concept unique, Christian Disty developpe une peinture plus personnelle, portee notamment par une serie sur le theme des drapes et un travail exploratoire autour de la resine. Il realise egalement des portraits sur commande d\'apres photographie, dans un style figuratif sensible qui prolonge, hors de la scene, son gout pour l\'illusion et le mouvement.\r\n\r\nEn 2015, ses creations sont recompensees lors du championnat du monde de magie par le prix du plus bel effet magique au monde en originalite.\r\n\r\nUn engagement au service des arts plastiques\r\n\r\nEngage dans la promotion des arts plastiques, Christian Disty devient president du Mouvement des Arts en 2019, avant d\'accompagner sa transformation en Federation des Arts Plastiques en 2025. Son action vise a soutenir les artistes a travers des evenements, conferences, ateliers et rencontres culturelles.\r\n\r\nSa devise resume son engagement : « Unissons nos forces pour valoriser les arts plastiques ! »', '/uploads/1787145689777.jpeg', '2026-08-19 13:14:47'),
(3, 'Lise Oerlemans', 'Peinture', 'Lise Oerlemans vit et travaille a Hyeres, ou elle est arrivee il y a plus de trente-cinq ans. Au fil du temps, elle y a construit un ancrage personnel et artistique fort, nourri par la lumiere et les paysages de la region.\r\n\r\nGuidee dans ses debuts par une artiste peintre qui lui a transmis l\'importance des jeux de lumiere, des ombres, du mouvement et des vibrations, Lise a progressivement affirme sa propre ecriture. Son travail se concentre aujourd\'hui sur la peinture a l\'huile au couteau, une technique qu\'elle utilise pour traduire l\'energie et la matiere de ses sujets.\r\n\r\nSes toiles representent principalement des paysages, inspires par ses voyages et ses rencontres avec la nature. Chaque oeuvre est l\'occasion de saisir une atmosphere, une lumiere fugace ou une emotion liee a un lieu, que Lise retranscrit avec une touche dynamique et une palette sensible.\r\n\r\nUne presence artistique ancree dans la duree\r\n\r\nInvestie de longue date dans la vie artistique locale, Lise Oerlemans a longtemps participe aux activites du Mouvement des Arts, aujourd\'hui devenu la Federation Francaise des Arts Plastiques, dont la transformation a ete officialisee en 2025. Elle expose chaque annee au Forum du Casino de Hyeres et est egalement presente toute l\'annee a la galerie de Giens, poursuivant ainsi un dialogue continu avec le public.', '/uploads/1787145689782.jpeg', '2026-08-19 13:14:47');
INSERT INTO `association` (`id`, `nom`, `logo`, `description`, `lien_externe`, `created_at`) VALUES
(2, 'Les Artistes Gardeens', '/uploads/1787326213478.jpg', 'Presidee par Martine de Santis\r\n\r\nL\'Association Les Artistes Gardeens est un exemple vivant de la maniere dont un atelier d\'art local peut stimuler la creativite et enrichir durablement la vie culturelle. Cette association offre bien plus qu\'un simple lieu d\'expression artistique : elle rassemble une veritable communaute ou artistes et amateurs d\'art se rencontrent pour apprendre, creer et partager leur passion.\r\n\r\nUn lieu dedie a l\'apprentissage et a la pratique artistique\r\nL\'association accueille chaleureusement les artistes de tous niveaux, des debutants aux createurs confirmes. Elle propose des ateliers, des cours et des seances de pratique libre permettant d\'explorer differentes disciplines telles que la peinture, la sculpture, le dessin et les techniques mixtes. Cette approche pratique encourage l\'experimentation, le developpement personnel et la progression artistique.\r\n\r\nElle met notamment a disposition : des ateliers adaptes a tous les niveaux, du materiel et des outils de qualite professionnelle, ainsi que l\'accompagnement d\'artistes et d\'intervenants experimentes.\r\n\r\nEn privilegiant la pratique, l\'association permet a chacun de developper ses competences tout en renforcant sa confiance en lui. A titre d\'exemple, un recent atelier consacre a la peinture a initie les participants a la theorie des couleurs et a la composition, avant de se conclure par une exposition collective mettant en valeur les oeuvres realisees.\r\n\r\nUne dynamique humaine et collective\r\nL\'un des plus grands atouts de l\'association reside dans sa capacite a creer une veritable dynamique humaine. Les artistes travaillent souvent de maniere isolee ; cet atelier leur offre un espace d\'echange, de collaboration et de dialogue. Les critiques collectives, les expositions et les rencontres conviviales permettent aux membres de partager leurs experiences et leur passion.\r\n\r\nUne ouverture vers le grand public\r\nL\'association s\'adresse egalement au grand public en organisant regulierement des expositions ouvertes a tous. Ces manifestations permettent aux artistes de presenter leurs creations en dehors de l\'atelier et favorisent les echanges avec les habitants autour de l\'art et de la culture.\r\nN\'hesitez pas a decouvrir ou a rejoindre l\'association afin de vivre pleinement l\'experience enrichissante que l\'art peut offrir a chacun.', NULL, '2026-08-21 15:30:13'),
(3, 'La Palette Valettoise', '/uploads/1787327364113.jpg', '83160 La Valette-du-Var\r\n\r\nUne histoire ancree dans la commune\r\nLa Palette Valettoise est une association Loi 1901, fondee en 1966 a La Valette-du-Var. C\'est la plus ancienne association de la commune. Depuis sa creation, les peintres amateurs peuvent donner libre cours a leur inspiration et a leur passion.\r\n\r\n« La Peinture est une poesie qui se voit. » — Leonard de Vinci\r\n\r\nNotre mission\r\nL\'association a pour objet de regrouper des artistes afin de favoriser les arts plastiques, en particulier la peinture, et toutes les activites qui s\'y rapportent, suivant les rythmes et les envies de chacune et de chacun. Pour cela, elle propose une information reguliere aupres de ses adherents, ainsi que l\'organisation d\'expositions, d\'echanges et de voyages culturels.\r\nNotre public se compose d\'adherents qui sont tous des peintres amateurs.\r\n\r\nLa vie de l\'atelier\r\nL\'atelier est ouvert trois apres-midis par semaine — le lundi, le mercredi et le vendredi, de 14h00 a 17h30. Chaque peintre dispose d\'un espace dedie et peut laisser l\'ensemble de son materiel sur place, dans des locaux adaptes ou regne une ambiance detendue, propice a la concentration. Des intervenants sont regulierement sollicites pour dispenser des cours de dessin et de peinture.\r\n\r\nNos rendez-vous et partenariats\r\nL\'association organise actuellement une exposition annuelle au printemps, a la Salle du Lavoir, a La Valette-du-Var. Elle est par ailleurs sollicitee plusieurs fois par an par la Municipalite pour participer a certains evenements (Telethon, Octobre Rose...) et organiser des ateliers de peinture pour les enfants, a l\'occasion de Noel, du Carnaval ou de la Fete de la Fraise. Ces ateliers remportent chaque fois un franc succes !\r\n\r\nNous rejoindre\r\nPeintres amateurs, debutants ou confirmes : La Palette Valettoise vous accueille dans un cadre convivial et stimulant, riche de pres de soixante ans d\'histoire.\r\nN\'hesitez pas a venir decouvrir l\'atelier et a rejoindre notre communaute de passionnes.', NULL, '2026-08-21 15:30:13'),
(4, 'Couleurs Revestoises', '/uploads/1787326213505.png', 'Association d\'artistes du Revest-les-Eaux', NULL, '2026-08-21 15:30:13');
